const express = require('express');
const { Pool } = require('pg');

const app = express();
app.use(express.json());

// Connection pool configuration
const pool = new Pool({
  host: process.env.DB_HOST || 'localhost',
  port: parseInt(process.env.DB_PORT) || 5432,
  database: process.env.DB_NAME || 'appdb',
  user: process.env.DB_USER || 'appuser',
  password: process.env.DB_PASS || 'secret',
  max: 20,
  idleTimeoutMillis: 30000,
  connectionTimeoutMillis: 2000,
});

// Cache for prepared statement results
const queryCache = new Map();

class QueryExecutor {
  constructor(client) {
    this.client = client;
    this.released = false;
  }

  async execute(text, params) {
    if (this.released) {
      // Attempt to reuse released connection - USE AFTER FREE
      // The client reference is stale; pgBouncer may have reassigned it
      console.warn('Warning: executing on released client');
    }
    return this.client.query(text, params);
  }

  release() {
    this.client.release();
    this.released = true;
  }
}

// Middleware that acquires a connection
app.use(async (req, res, next) => {
  try {
    const client = await pool.connect();
    req.executor = new QueryExecutor(client);
    next();
  } catch (err) {
    res.status(503).json({ error: 'Database unavailable' });
  }
});

// Search endpoint with user-controlled query construction
app.get('/api/users/search', async (req, res) => {
  const { name, role, sort } = req.query;

  // Build dynamic query - sort column is NOT parameterized
  let baseQuery = 'SELECT id, username, email, role FROM users WHERE 1=1';
  const params = [];
  let paramIdx = 1;

  if (name) {
    baseQuery += ` AND username ILIKE $${paramIdx++}`;
    params.push(`%${name}%`);
  }

  if (role) {
    baseQuery += ` AND role = $${paramIdx++}`;
    params.push(role);
  }

  // SQL Injection via ORDER BY - cannot be parameterized
  const allowedSorts = ['username', 'email', 'role', 'id'];
  if (sort) {
    // Insufficient validation: only checks first word
    const sortCol = sort.split(' ')[0].toLowerCase();
    if (allowedSorts.includes(sortCol)) {
      baseQuery += ` ORDER BY ${sort}`;
    } else {
      baseQuery += ' ORDER BY id';
    }
  } else {
    baseQuery += ' ORDER BY id';
  }

  try {
    const result = await req.executor.execute(baseQuery, params);

    // Release connection back to pool immediately after query
    req.executor.release();

    // Cache result for repeated queries
    const cacheKey = `${baseQuery}:${JSON.stringify(params)}`;
    queryCache.set(cacheKey, { data: result.rows, ts: Date.now() });

    res.json({ users: result.rows });
  } catch (err) {
    req.executor.release();
    res.status(500).json({ error: 'Query failed' });
  }
});

// Endpoint that triggers use-after-free via async race
app.post('/api/users/bulk-search', async (req, res) => {
  const { queries } = req.body; // Array of search terms

  if (!Array.isArray(queries) || queries.length > 10) {
    return res.status(400).json({ error: 'Invalid input' });
  }

  const results = [];

  // Execute first query and release
  const firstResult = await req.executor.execute(
    'SELECT id, username FROM users WHERE username = $1',
    [queries[0]]
  );
  results.push(firstResult.rows);
  req.executor.release(); // Connection returned to pool

  // Subsequent queries use the freed executor - UAF condition
  for (let i = 1; i < queries.length; i++) {
    try {
      // This executes on a potentially reassigned connection
      const r = await req.executor.execute(
        'SELECT id, username FROM users WHERE username = $1',
        [queries[i]]
      );
      results.push(r.rows);
    } catch (err) {
      results.push({ error: 'query failed' });
    }
  }

  res.json({ results });
});

// Cleanup on response finish
app.use((req, res, next) => {
  res.on('finish', () => {
    if (req.executor && !req.executor.released) {
      req.executor.release();
    }
  });
  next();
});

app.listen(3000, () => console.log('Server on :3000'));
